export default {
  title: "Design System/Molecules/MetricWidget",
  component: MetricWidget,
  parameters: {
    docs: {
      description: {
        component: `
The MetricWidget component displays metrics with a heading and content section.

**Heading Prop Types:**
- **String**: Simple text heading (backward compatible). Automatically styled with subline variant and uppercase transform.
- **ReactNode**: Custom React elements for complex layouts. Use this when you need interactive elements, multiple components, or custom styling in the heading.

**Layout Structure:**
- Container: Flex with flexDirection: "column"
- Heading section: Renders the heading prop (string or ReactNode) with justifyContent: "space-between"
- Content section: Renders the content prop (ReactNode)

**When to use string vs ReactNode for heading:**
- Use **string** for simple text labels
- Use **ReactNode** when you need:
  - Interactive elements (e.g., Selector)
  - Multiple components side-by-side
  - Custom spacing or layout
  - Complex styling requirements

**Space-between Layout:**
The heading section uses justifyContent: "space-between" to distribute space between its children. This is particularly useful when using a Flex container with multiple elements (e.g., text on the left, selector on the right).
        `,
      },
    },
  },
  argTypes: {
    heading: {
      control: "text",
      description: "Heading text (string) or custom React element (ReactNode)",
    },
    content: {
      control: "text",
      description: "Content to display (ReactNode)",
    },
    tooltipContent: {
      control: "text",
      description: "Tooltip content (string or ReactNode)",
    },
    isLoading: {
      control: "boolean",
      description: "Show loading skeleton",
    },
    status: {
      control: "select",
      options: ["active", "pending", "exited", "inactive"],
      description: "Validator status (mutually exclusive with content)",
    },
  },
} as Meta<typeof MetricWidget>;

