const InteractivePeriodSelectorComponent = () => {
  const [selectedPeriod, setSelectedPeriod] = useState<Period>("1m");

  const getRewardAmount = (period: Period) => {
    switch (period) {
      case "1d":
        return { eth: "0.123 ETH", usd: "$123.45" };
      case "1m":
        return { eth: "3.456 ETH", usd: "$3,456.78" };
      case "1y":
        return { eth: "42.789 ETH", usd: "$42,789.01" };
      default:
        return { eth: "0 ETH", usd: "$0.00" };
    }
  };

  const rewards = getRewardAmount(selectedPeriod);

  return (
    <MetricWidget
      heading={
        <Flex
          css={{
            justifyContent: "space-between",
            alignItems: "baseline",
            width: "100%",
          }}
        >
          <Text variant="subline" color="body" css={{ textTransform: "uppercase" }}>
            Rewards
          </Text>
          <Selector
            selectedValue={selectedPeriod}
            onValueChange={setSelectedPeriod}
            options={PERIOD_OPTIONS}
          />
        </Flex>
      }
      content={
        <Flex
          css={{
            justifyContent: "space-between",
            alignItems: "center",
            width: "100%",
          }}
        >
          <Text variant="h4">{rewards.eth}</Text>
          <Text variant="body" color="muted">
            {rewards.usd}
          </Text>
        </Flex>
      }
    />
  );
};

